RiffleLowerV2.Ascent.badLeftBoundaries.e.type:
∀ {N : ℕ} (G : RiffleLowerV2.PathEdges N) (H : Finset (Fin N)),
  RiffleLowerV2.Ascent.badLeftBoundaries G H =
    {e ∈ RiffleLowerV2.Ascent.retainedBoundaries G H | ¬RiffleLowerV2.Ascent.leftComponent G e ⊆ H}

RiffleLowerV2.Ascent.badRightBoundaries..type:
∀ {N : ℕ} (G : RiffleLowerV2.PathEdges N) (H : Finset (Fin N)),
  RiffleLowerV2.Ascent.badRightBoundaries G H =
    {e ∈ RiffleLowerV2.Ascent.retainedBoundaries G H | ¬RiffleLowerV2.Ascent.rightComponent G e ⊆ H}

RiffleLowerV2.Ascent.boundary_left_index.type:
∀ {N : ℕ} (G : RiffleLowerV2.PathEdges N),
  Set.InjOn (fun (e : Fin (N - 1)) => RiffleLowerV2.componentIndex G (RiffleLowerV2.edgeLeft e))
    {e : Fin (N - 1) | e ∉ G}

RiffleLowerV2.Ascent.boundary_right_inde.type:
∀ {N : ℕ} (G : RiffleLowerV2.PathEdges N),
  Set.InjOn (fun (e : Fin (N - 1)) => RiffleLowerV2.componentIndex G (RiffleLowerV2.edgeRight e))
    {e : Fin (N - 1) | e ∉ G}

RiffleLowerV2.Ascent.leftPositionAction.value:
fun {N : ℕ} (ρ : RiffleLowerV2.Permutation N) =>
  { toFun := fun (π : RiffleLowerV2.Permutation N) => Equiv.trans ρ π,
    invFun := fun (π : RiffleLowerV2.Permutation N) => (Equiv.symm ρ).trans π, left_inv := ⋯, right_inv := ⋯ }

RiffleLowerV2.Ascent.orderTransform.value:
fun {n : ℕ} (ρ : Equiv.Perm (Fin n)) =>
  { toFun := fun (η : Equiv.Perm (Fin n)) => Equiv.trans ρ (Equiv.symm η),
    invFun := fun (η : Equiv.Perm (Fin n)) => (Equiv.symm η).trans ρ, left_inv := ⋯, right_inv := ⋯ }

RiffleLowerV2.Ascent.successfulTranslate.type:
∀ {N : ℕ} (H0 : Finset ℤ) (G : RiffleLowerV2.PathEdges N) (r : ℝ),
  RiffleLowerV2.Ascent.successfulTranslates H0 G r =
    {q : Fin (N + 1) | r ≤ ↑(Finset.card (G ∩ RiffleLowerV2.internalEdges (RiffleLowerV2.clipTranslate N H0 ↑↑q)))}

RiffleLowerV2.Ascent.swapPositions.value:
fun {N : ℕ} (i j : Fin N) =>
  { toFun := fun (π : RiffleLowerV2.Permutation N) => Equiv.trans (Equiv.swap i j) π,
    invFun := fun (π : RiffleLowerV2.Permutation N) => Equiv.trans (Equiv.swap i j) π, left_inv := ⋯, right_inv := ⋯ }
